import {readInvoicePhoto,scanInvoicePixels,parseInvoiceQR} from './invoice-scan.mjs';
import {money,cents,today,categoryList} from './domain.mjs';
import {saveInvoice,invoiceExpense,unlinkInvoice,deleteInvoice,previewInvoiceCSV,importInvoices,invoiceCSV,invoiceMatches} from './invoice-core.mjs';
export function createInvoiceUI(c){
  const {E,I,toast,openSheet,download}=c,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let search='',scanGeneration=0,scanImage='',scanController=null;
  $('#sheet').addEventListener('close',()=>{scanGeneration++;scanImage='';scanController?.abort();});
  const source={cloud:'雲端（手動紀錄）',paper:'紙本',other:'其他'},reimburse={none:'不需報帳',pending:'待報帳',submitted:'已送出',paid:'已核銷'};
  const field=(label,id,value='',type='text',extra='')=>`<label class="field">${label}<input id="${id}" type="${type}" value="${E(value)}" ${extra}></label>`;
  const select=(label,id,values,value)=>`<label class="field">${label}<select id="${id}">${values.map(([k,v])=>`<option value="${E(k)}" ${k===value?'selected':''}>${E(v)}</option>`).join('')}</select></label>`;
  const finish=next=>{if(c.commit(next)){c.render();$('#sheet').close();return true;}return false;};
  function page(){
    const state=c.getState(),rows=(state.invoices||[]).filter(v=>v.date.startsWith(c.getMonth())&&[v.number,v.seller,v.carrier,v.note].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));
    const total=rows.filter(v=>v.status==='active').reduce((n,v)=>n+v.amount,0);
    return `<div class="page-title"><div><div class="eyebrow">YOUR RECEIPTS, TOGETHER</div><h1>每張發票，都有去處。</h1><p class="subtitle">整理雲端與紙本發票，先核對，再連結帳目。</p></div><div class="controls"><button class="secondary" id="invoice-scan">${I('camera')}掃描／拍發票</button><button class="secondary" id="invoice-match">付款配對助手</button><button class="secondary" id="invoice-import">匯入 CSV</button><button class="primary" id="invoice-add">${I('plus')}新增發票</button></div></div><div class="notice">支援照片 QR Code 本機讀取、AI 發票辨識、手動與 CSV 匯入；尚未連接財政部載具自動下載。新增發票不會增加支出，確認後才入帳或配對。</div><div class="stat-grid" style="margin-top:20px">${[['本月發票',rows.length+' 張'],['有效發票總額',money(total)],['未關聯帳目',rows.filter(v=>!v.txId&&v.status==='active').length+' 張']].map(([l,v])=>`<div class="card"><div class="card-label">${l}</div><div class="metric-value sensitive">${E(v)}</div></div>`).join('')}</div><div class="card"><div class="card-heading"><h2>發票紀錄 · ${E(c.getMonth())}</h2><div class="row"><button class="text-btn" id="invoice-export">匯出發票 CSV</button><button class="text-btn" id="invoice-template">下載匯入範本</button></div></div><label class="field">搜尋發票／店家／載具<input type="search" id="invoice-search" value="${E(search)}" placeholder="輸入號碼或關鍵字"></label>${rows.length?rows.map(v=>{const tx=state.transactions.find(t=>t.id===v.txId);return `<div class="due-row invoice-row"><div><strong>${E(v.seller)} · ${E(v.number)}</strong><small>${E(v.date)} · ${source[v.source]}${v.carrier?' · '+E(v.carrier):''}<br>${v.status==='void'?'已作廢 · ':''}${reimburse[v.reimbursement]} · ${v.txId?(tx?'已關聯帳目'+(tx.amount!==v.amount?'（金額不一致，請核對）':''):'原帳目已刪除，請核對'):'尚未入帳'}${v.note?'<br>'+E(v.note):''}</small></div><strong class="sensitive">${money(v.amount)}</strong><div class="invoice-actions">${!v.txId&&v.status==='active'?`<button class="text-btn" data-invoice-book="${E(v.id)}">入帳／連結</button>`:''}<button class="text-btn" data-invoice-edit="${E(v.id)}">編輯</button><button class="text-btn" data-invoice-delete="${E(v.id)}">刪除</button></div></div>`;}).join(''):'<div class="empty-state">這個月份還沒有符合的發票。新增或匯入後，會出現在這裡。</div>'}<input type="file" id="invoice-file" accept=".csv,text/csv" hidden></div><p class="help">來源標記不代表已向財政部驗證、取得雲端專屬獎資格或具有報帳憑證效力。此頁不儲存載具驗證碼、不自動對獎；作廢或刪除發票不會自行更改已入帳支出，請另行核對退款。</p>`;
  }
  function edit(id=null,prefill=null){const v=c.getState().invoices?.find(v=>v.id===id)||prefill;openSheet(id?'編輯發票':'新增發票',` ${v?.warning?'<div class="notice">'+E(v.warning)+'</div>':''}<form id="invoice-form"><div class="row">${field('發票號碼','inv-number',v?.number||'','text','required maxlength="11" placeholder="AB12345678"')}${field('發票日期','inv-date',v?v.date:today(),'date','required')}</div>${field('店家名稱','inv-seller',v?.seller||'','text','required maxlength="200"')}<div class="row">${field('含稅總金額（NT$）','inv-amount',v?.amount!=null?v.amount/100:'','number','required min="0.01" step="0.01"')}${select('來源','inv-source',Object.entries(source),v?.source||'cloud')}</div>${field('載具註記（可留空）','inv-carrier',v?.carrier||'','text','maxlength="100" placeholder="例如：手機條碼、全聯會員"')}${field('賣方統編（可留空）','inv-tax',v?.sellerTaxId||'','text','pattern="[0-9]{8}" maxlength="8"')}<div class="row">${select('發票狀態','inv-status',[['active','有效'],['void','作廢']],v?.status||'active')}${select('報帳進度','inv-reimburse',Object.entries(reimburse),v?.reimbursement||'none')}</div>${field('備註','inv-note',v?.note||'','text','maxlength="500"')}${v?.txId?'<p class="help">此發票已有帳目關聯。作廢不會自動沖銷支出；請核對是否另有退款。</p><button type="button" class="secondary" id="invoice-unlink">解除帳目關聯（不刪除交易）</button>':''}<div id="invoice-error" class="inline-error" role="alert"></div><button class="primary full" style="margin-top:16px">儲存發票紀錄</button></form>`);$('#invoice-form').onsubmit=e=>{e.preventDefault();try{if(finish(saveInvoice(c.getState(),{number:$('#inv-number').value,date:$('#inv-date').value,seller:$('#inv-seller').value,amount:cents($('#inv-amount').value),source:$('#inv-source').value,carrier:$('#inv-carrier').value,sellerTaxId:$('#inv-tax').value,note:$('#inv-note').value,status:$('#inv-status').value,reimbursement:$('#inv-reimburse').value},id)))toast('發票已儲存，未新增支出');}catch(err){$('#invoice-error').textContent=err.message;}};$('#invoice-unlink')?.addEventListener('click',()=>{if(confirm('只解除發票與交易的關聯，原支出仍保留。重新入帳可能重複，確定嗎？'))finish(unlinkInvoice(c.getState(),id));});}
  function book(id){const state=c.getState(),v=state.invoices.find(v=>v.id===id),ranked=invoiceMatches(state,id),rankIds=new Set(ranked.map(v=>v.tx.id)),matches=[...ranked.map(v=>v.tx),...state.transactions.filter(t=>t.type==='expense'&&t.amount===v.amount&&!state.invoices.some(i=>i.txId===t.id)&&!rankIds.has(t.id))];openSheet('核對發票與帳目',`<form id="invoice-book-form"><p class="help">${E(v.number)} · ${E(v.seller)} · ${money(v.amount)}</p>${select('記錄方式','inv-existing',[['','新增一筆支出'],...matches.slice(0,100).map(t=>[t.id,t.date+' · '+t.note+' · '+money(t.amount)+(ranked.find(v=>v.tx.id===t.id)?' · 建議核對':'')])],'')}<p class="help">若已經記過這筆消費，請選擇相同金額的既有支出。連結不會新增交易。</p>${select('新增支出的付款帳戶','inv-account',state.accounts.filter(a=>a.kind!=='receivable').map(a=>[a.id,a.name]),state.accounts[0].id)}${select('新增支出的分類','inv-category',categoryList(state).map(v=>[v,v]),'其他')}${select('新增支出的帳本','inv-book',state.features.books.map(b=>[b.id,b.name]),c.getBook()==='all'?'personal':c.getBook())}<div class="inline-error" id="invoice-book-error" role="alert"></div><button class="primary full">確認入帳／連結</button></form>`);$('#invoice-book-form').onsubmit=e=>{e.preventDefault();try{if(finish(invoiceExpense(c.getState(),id,{existingTxId:$('#inv-existing').value||null,account:$('#inv-account').value,category:$('#inv-category').value,bookId:$('#inv-book').value})))toast('發票與帳目已關聯');}catch(err){$('#invoice-book-error').textContent=err.message;}};}
  function matchAssistant(){const state=c.getState(),rows=(state.invoices||[]).filter(v=>v.status==='active'&&!v.txId).sort((a,b)=>b.date.localeCompare(a.date));openSheet('付款與發票配對助手',`<p class="help">依相同金額、前後7天與店家名稱找候選，仍需你逐張確認；已被其他發票使用的交易會略過。</p>${rows.slice(0,100).map(v=>{const matches=invoiceMatches(state,v.id);return `<div class="match-card"><strong>${E(v.seller)} · ${E(v.number)} · ${money(v.amount)}</strong><p class="help">${E(v.date)} · ${matches.length?matches.length+'筆候選':'未找到相近日期與同額支出，可手動核對'}</p>${matches.slice(0,3).map(m=>`<div class="due-row"><div><strong>${E(m.tx.note)}</strong><small>${E(m.tx.date)} · ${E(state.accounts.find(a=>a.id===m.tx.account)?.name)} · ${E(m.reason)}</small></div><button class="secondary" data-match-invoice="${E(v.id)}" data-match-transaction="${E(m.tx.id)}">確認連結</button></div>`).join('')}<button class="text-btn" data-match-manual="${E(v.id)}">其他帳目／新增支出</button></div>`;}).join('')||'<p class="help">目前沒有待配對的有效發票。</p>'}`);$$('[data-match-invoice]').forEach(b=>b.onclick=()=>{try{if(c.commit(invoiceExpense(c.getState(),b.dataset.matchInvoice,{existingTxId:b.dataset.matchTransaction}))){c.render();toast('已連結既有支出，未新增交易');matchAssistant();}}catch(e){toast(e.message);}});$$('[data-match-manual]').forEach(b=>b.onclick=()=>book(b.dataset.matchManual));}
  function scanner(){const scope=c.getStorageKey(),generation=++scanGeneration;let photoRequest=0;scanImage='';scanController?.abort();scanController=new AbortController();openSheet('掃描／拍攝發票',`<p class="help">先讀取照片中的左側 QR Code，全程在此裝置處理。若沒有 QR Code，可選擇把這張圖片交給 Google AI 辨識；結果先預覽，不自動入帳。</p><div class="row" style="flex-wrap:wrap"><button class="primary" id="invoice-camera-pick">${I('camera')}拍一張發票</button><button class="secondary" id="invoice-photo-pick">選擇照片</button></div><input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" id="invoice-camera-file" hidden><input type="file" accept="image/jpeg,image/png,image/webp" id="invoice-photo-file" hidden><div id="invoice-scan-preview" style="margin-top:16px"></div><div class="notice" id="invoice-scan-result" role="status">請選擇發票照片，對準左側方碼並保持清晰。</div><button class="secondary full" id="invoice-ai-scan" disabled style="margin-top:16px">AI 辨識這張圖片（傳送 Google）</button><details style="margin-top:20px"><summary>已有 QR Code 文字內容</summary><label class="field">左側 QR Code 原始內容<textarea id="invoice-qr-text" rows="3" maxlength="12000"></textarea></label><button class="secondary" id="invoice-qr-parse">讀取並預覽</button></details><p class="help">照片只用於本次辨識，不加入帳本或備份。QR Code 不含可直接使用的店家名稱時，請自行補上；目前僅自動解析國內台幣格式，不代表已驗證發票真偽。</p>`);
    const current=()=>generation===scanGeneration&&scope===c.getStorageKey()&&!!$('#invoice-scan-result');
    const showDraft=v=>{if(!current())return;scanGeneration++;scanImage='';scanController?.abort();edit(null,v);};
    async function choose(e){const file=e.target.files[0];if(!file)return;const request=++photoRequest;scanController?.abort();scanController=new AbortController();try{const photo=await readInvoicePhoto(file);if(!current()||request!==photoRequest)return;scanImage=photo.image;$('#invoice-scan-preview').innerHTML='<img class="image-preview" alt="本次發票照片">';$('#invoice-scan-preview img').src=scanImage;$('#invoice-ai-scan').disabled=false;$('#invoice-scan-result').textContent='正在裝置上讀取 QR Code…';try{const draft=await scanInvoicePixels(photo.pixels.data,photo.pixels.width,photo.pixels.height);if(request===photoRequest)showDraft(draft);}catch(err){if(current())$('#invoice-scan-result').textContent=err.message+'。可改用 AI 辨識或手動輸入。';}}catch(err){if(current())$('#invoice-scan-result').textContent=err.message;}finally{e.target.value='';}}
    $('#invoice-camera-pick').onclick=()=>$('#invoice-camera-file').click();$('#invoice-photo-pick').onclick=()=>$('#invoice-photo-file').click();$('#invoice-camera-file').onchange=choose;$('#invoice-photo-file').onchange=choose;
    $('#invoice-qr-parse').onclick=()=>{try{showDraft(parseInvoiceQR($('#invoice-qr-text').value));}catch(e){$('#invoice-scan-result').textContent=e.message;}};
    $('#invoice-ai-scan').onclick=async()=>{if(!scanImage||!current())return;const request=photoRequest;const button=$('#invoice-ai-scan');button.disabled=true;try{const draft=await c.extractInvoicePhoto(scanImage,{signal:scanController.signal,onStatus:v=>{if(current())$('#invoice-scan-result').textContent=v.message;}});if(request===photoRequest)showDraft(draft);}catch(e){if(current())$('#invoice-scan-result').textContent=e.message;}finally{if(button.isConnected)button.disabled=false;}};
  }
  function bind(){
    $('#invoice-scan')?.addEventListener('click',scanner);$('#invoice-match')?.addEventListener('click',matchAssistant);
    $('#invoice-add')?.addEventListener('click',()=>edit());$('#invoice-search')?.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;c.render();$('#invoice-search').focus();$('#invoice-search').setSelectionRange(pos,pos);});
    $$('[data-invoice-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.invoiceEdit));$$('[data-invoice-book]').forEach(b=>b.onclick=()=>book(b.dataset.invoiceBook));$$('[data-invoice-delete]').forEach(b=>b.onclick=()=>{if(confirm('刪除這張發票紀錄？已入帳交易會保留，仍可從完整備份／歷史版本找回發票。'))finish(deleteInvoice(c.getState(),b.dataset.invoiceDelete));});
    $('#invoice-export')?.addEventListener('click',()=>download(invoiceCSV(c.getState()),'日常有餘_發票_'+today()+'.csv','text/csv;charset=utf-8'));
    $('#invoice-template')?.addEventListener('click',()=>download('\uFEFF發票號碼,日期,店家,含稅金額,來源,載具,賣方統編,備註\r\nAB12345678,'+today()+',範例店家,150,cloud,手機條碼,,請刪除此範例後填入自己的紀錄\r\n','日常有餘_發票匯入範本.csv','text/csv;charset=utf-8'));
    $('#invoice-import')?.addEventListener('click',()=>$('#invoice-file').click());
    $('#invoice-file')?.addEventListener('change',async e=>{const file=e.target.files[0],scope=c.getStorageKey();if(!file)return;try{if(file.size>5*1024*1024)throw Error('CSV 超過5MB');const preview=previewInvoiceCSV(await file.text(),c.getState());if(scope!==c.getStorageKey())throw Error('帳號已切換，請重新匯入');openSheet('核對發票匯入',`<p class="help">可匯入 ${preview.candidates.length} 張；重複 ${preview.duplicates.length} 張將略過；錯誤 ${preview.errors.length} 筆。匯入只新增發票，不增加支出。</p>${preview.errors.length?'<div class="notice error">請先修正檔案，避免漏匯入：'+preview.errors.map(v=>'第'+v.row+'列：'+E(v.message)).join('<br>')+'</div>':''}<div class="schedule-list">${preview.candidates.slice(0,20).map(v=>`<p class="help">${E(v.date)} · ${E(v.number)} · ${E(v.seller)} · ${money(v.amount)}</p>`).join('')}</div><button class="primary full" id="invoice-import-confirm" ${preview.errors.length||!preview.candidates.length?'disabled':''}>確認匯入 ${preview.candidates.length} 張</button>`);$('#invoice-import-confirm').onclick=()=>{try{if(scope!==c.getStorageKey())throw Error('帳號已切換，請重新匯入');if(finish(importInvoices(c.getState(),preview.candidates)))toast('發票已匯入，未新增支出');}catch(err){toast(err.message);}};}catch(err){toast(err.message);}finally{e.target.value='';}});
  }
  return {page,bind};
}
